def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    # find wall
    wall = None
    for y, name in [(0, 'top'), (H-1, 'bottom')]:
        r = g[y]
        if r[0] != bg and np.all(r == r[0]):
            wall = name
    for x, name in [(0, 'left'), (W-1, 'right')]:
        c = g[:, x]
        if c[0] != bg and np.all(c == c[0]):
            wall = name
    dy, dx = {'top': (-1, 0), 'bottom': (1, 0), 'left': (0, -1), 'right': (0, 1)}[wall]
    out = g.copy()
    objs = objects(g, bg=bg)
    wallcol = None
    if wall == 'top': wallcol = set((0, x) for x in range(W))
    if wall == 'bottom': wallcol = set((H-1, x) for x in range(W))
    if wall == 'left': wallcol = set((y, 0) for y in range(H))
    if wall == 'right': wallcol = set((y, W-1) for y in range(H))
    movers = [o for o in objs if not set(o["cells"]) <= wallcol]

    def dist(o):
        if wall == 'top': return min(y for y, x in o["cells"])
        if wall == 'bottom': return min(H-1-y for y, x in o["cells"])
        if wall == 'left': return min(x for y, x in o["cells"])
        return min(W-1-x for y, x in o["cells"])

    movers.sort(key=dist)
    for o in movers:
        cells = o["cells"]
        col = o["colour"]
        for y, x in cells:
            out[y, x] = bg
        k = 0
        while True:
            ok = True
            for y, x in cells:
                ny, nx = y + dy*(k+1), x + dx*(k+1)
                if not (0 <= ny < H and 0 <= nx < W) or out[ny, nx] != bg:
                    ok = False
                    break
            if not ok:
                break
            k += 1
        for y, x in cells:
            out[y + dy*k, x + dx*k] = col
        emit(out, f"Slide the colour-{col} piece toward the {wall} wall until it rests against the wall or a settled piece.")
    emit(out, "All pieces have settled against the wall.")
    return out
